   <main class="support-card">
     <h1>Contact Support</h1>
     <p class="intro">Send your details and our support team will get back to you as soon as possible.</p>

     <form id="support-form" novalidate>
       <div class="form-field">
         <label for="full-name">Full name</label>
         <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required>
         <p class="error-text" aria-live="polite"></p>
       </div>

       <div class="form-field">
         <label for="email-address">Email address</label>
         <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required>
         <p class="error-text" aria-live="polite"></p>
       </div>

       <div class="form-field">
         <label for="phone-number">Phone number</label>
         <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+1 555 123 4567">
         <p class="helper-text">Optional. Use digits with spaces, dashes, or a leading +, for example: +1 555 123 4567.</p>
         <p class="error-text" aria-live="polite"></p>
       </div>

       <button type="submit">Submit</button>
     </form>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const fields = Array.from(form.querySelectorAll(".form-field"));

     const validators = {
       fullName(value) {
         return value.trim() ? "" : "Full name is required.";
       },
       email(value) {
         if (!value.trim()) {
           return "Email address is required.";
         }

         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         return emailPattern.test(value.trim()) ? "" : "Enter a valid email address.";
       },
       phone(value) {
         if (!value.trim()) {
           return "";
         }

         const phonePattern = /^\+?[0-9\s\-()]{7,20}$/;
         return phonePattern.test(value.trim()) ? "" : "Use a valid phone number format.";
       }
     };

     function setFieldState(fieldWrapper, message) {
       const errorText = fieldWrapper.querySelector(".error-text");
       fieldWrapper.classList.toggle("invalid", Boolean(message));
       errorText.textContent = message;
     }

     function validateField(input) {
       const fieldWrapper = input.closest(".form-field");
       const message = validators[input.name](input.value);
       setFieldState(fieldWrapper, message);
       return !message;
     }

     fields.forEach((fieldWrapper) => {
       const input = fieldWrapper.querySelector("input");

       input.addEventListener("blur", () => {
         validateField(input);
       });

       input.addEventListener("input", () => {
         if (fieldWrapper.classList.contains("invalid")) {
           validateField(input);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const allValid = fields
         .map((fieldWrapper) => validateField(fieldWrapper.querySelector("input")))
         .every(Boolean);

       if (allValid) {
         form.reset();
         fields.forEach((fieldWrapper) => setFieldState(fieldWrapper, ""));
         alert("Your support request has been submitted.");
       }
     });
   </script>
 </body>
 </html>

